pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _log) public {
        vm.assume(_log != address(0));
        c.Initialized();
        c.SetLogFile(_log);
        // Access Log via AddMessage. Since Put is public payable 
        // and internally calls Log.AddMessage, we use Put to trigger it.
        // Then we check if History length increased.
        // First, fetch current History length.
        // We need to call a LogFile view; Log is internal, but we can call
        // C.Put which calls Log.AddMessage. We then check via LogFile getter
        // for History that is public. But Log variable is internal and has no getter.
        // Since Log is internal, we cannot read it directly.
        // However, we can observe the effect via the fallback which calls Put,
        // but Put requires a Log contract that is not zero or it will revert 
        // on Log.AddMessage (invalid address call).
        // So we try: send eth to C which triggers fallback -> Put(0) -> Log.AddMessage.
        // If Log is zero, AddMessage call will revert; if non-zero, succeed.
        vm.deal(address(this), 1 ether);
        (bool ok,) = address(c).call{value: 1 ether}("");
        assertTrue(ok);
    }
}

