pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 putAmount, uint256 collectAmount, uint256 warpTime) public {
        // Bound parameters to reasonable ranges
        lockTime = bound(lockTime, 0, type(uint256).max - 1);
        putAmount = bound(putAmount, 0, type(uint128).max);
        collectAmount = bound(collectAmount, 1, type(uint128).max);
        warpTime = bound(warpTime, 1, type(uint256).max - 1);

        // Set up the contract: initialize MinSum and deploy Log
        address logAddr = address(new LogFile());
        c.SetMinSum(0);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Use a fresh address as the caller
        address actor = address(0x12345);
        vm.deal(actor, putAmount);

        // Warp to the specified timestamp
        vm.warp(warpTime);

        // Actor puts Ether with a lock time
        vm.prank(actor);
        c.Put{value: putAmount}(lockTime);

        // Record balance before Collect
        uint256 balanceBefore = actor.balance;

        // Attempt Collect; in reference it reverts if conditions not met, in buggy it might succeed due to overflow
        bool ok;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If Collect succeeded, the actor's balance must have increased by exactly collectAmount
        // (the reference ensures this; buggy may either succeed when reference would revert or leave different balance)
        if (ok) {
            uint256 balanceAfter = actor.balance;
            uint256 expected = balanceBefore + collectAmount;
            assertTrue(balanceAfter == expected);
        } else {
            assertTrue(true);
        }
    }
}

