pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
    }

    function testFuzz_property(address sender, uint256 amount, uint256 lockTime, uint256 warpDelta) public {
        vm.assume(sender != address(0));
        vm.assume(amount > 0);
        // Ensure lockTime is a future offset that does not overflow
        vm.assume(lockTime > 0 && lockTime < type(uint256).max - uint256(type(uint64).max));
        // warpDelta controls when we attempt to collect relative to the put
        vm.assume(warpDelta <= lockTime + 1);

        // Fund the sender and make a Put with a future lockTime
        vm.deal(sender, amount);
        vm.startPrank(sender);
        c.Put{value: amount}(lockTime);
        vm.stopPrank();

        // Record the unlockTime after Put
        (uint256 unlockTimeAfterPut,) = c.Acc(sender);

        // Warp forward by warpDelta
        vm.warp(block.timestamp + warpDelta);

        // Attempt to Collect the full amount
        vm.startPrank(sender);
        bool ok;
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // Rule: if Collect succeeds (ok == true), then block.timestamp must be > unlockTimeAfterPut
        // The buggy version removes the unlockTime update, so unlockTimeAfterPut remains 0,
        // allowing Collect to succeed even when warpDelta < lockTime (i.e. timestamp <= original expected unlockTime)
        assertTrue(!ok || block.timestamp > unlockTimeAfterPut);
    }

    function _logFile() internal view returns (LogFile) {
        return LogFile(address(c.Log()));
    }
}

